#include <iostream>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int S, T;
    cin >> S >> T;

    vector<vector<bool>> connected(S + 1, vector<bool>(S + 1, false));

    for (int i = 0; i < T; ++i) {
        int x, y;
        cin >> x >> y;
        connected[x][y] = connected[y][x] = true;
    }

    int P;
    cin >> P;

    int possible = 0;
    for (int i = 0; i < P; ++i) {
        int N;
        cin >> N;

        int previous, current;
        cin >> previous;
        bool valid = true;

        for (int j = 1; j < N; ++j) {
            cin >> current;
            if (!connected[previous][current]) valid = false;
            previous = current;
        }

        if (valid) ++possible;
    }

    cout << possible << '\n';
    return 0;
}
